function renderInspector(){const el=$("#inspector");if(!app.selected){el.innerHTML='<div class="empty-inspector"><span>◇</span><p>カード・線・領域を選択すると<br>詳細を編集できます</p></div>';return}const {type,id}=app.selected;if(type==="card"){const c=card(id);if(!c)return clearSelection();const groupField=`<label class="field"><span>親グループ</span><select id="i-parent-group"><option value="">なし（位置から自動判定）</option>${flow().groups.map(g=>`<option value="${g.id}" ${c.groupId===g.id?"selected":""}>${esc(g.name)}</option>`).join("")}</select></label>`;el.innerHTML=`<h2>カードの詳細</h2><label class="field"><span>タイトル</span><input id="i-title" value="${attr(c.title)}"></label><label class="field"><span>展開メモ</span><textarea id="i-body">${esc(c.body)}</textarea></label><label class="field"><span>タグ（カンマ区切り）</span><input id="i-tags" value="${attr(c.tags.join(", "))}"></label>${groupField}<p class="hint">サイズ ${cardWidth(c)} × ${cardHeight(c)}px。右端で期間、下端で高さを変更できます。</p><div class="inspector-actions"><button id="i-connect">接続先を選択</button><button id="i-collapse">${c.collapsed?"メモを展開":"メモを閉じる"}</button><button id="i-delete" class="danger">削除</button></div><p class="hint">キャンバス上では、カードを右クリックしたまま接続先へドラッグします。</p>`;bindInput("#i-title",v=>c.title=v);bindInput("#i-body",v=>c.body=v);bindInput("#i-tags",v=>c.tags=[...new Set(v.split(",").map(x=>x.trim().replace(/^#/ ,"")).filter(Boolean))]);$("#i-parent-group").addEventListener("change",e=>{history();c.groupId=e.target.value;persist();render()});$("#i-collapse").onclick=()=>mutate(()=>c.collapsed=!c.collapsed);$("#i-delete").onclick=()=>deleteEntity("card",id);$("#i-connect").onclick=()=>chooseConnectionTarget(id)}
else if(type==="edge"){const x=edge(id);if(!x)return clearSelection();const kind=x.kind||"normal",arc=kind!=="normal"?`<label class="field"><span>円弧の高さ（px）</span><input id="i-arc-height" type="number" min="75" step="25" value="${Number(x.arcHeight)||100}"></label>`:"";el.innerHTML=`<h2>接続線の詳細</h2><label class="field"><span>線の種類</span><select id="i-edge-kind"><option value="normal" ${kind==="normal"?"selected":""}>通常フロー</option><option value="loopTop" ${kind==="loopTop"?"selected":""}>1：上側の戻りループ</option><option value="loopBottom" ${kind==="loopBottom"?"selected":""}>2：下側の差し戻し</option><option value="self" ${kind==="self"?"selected":""}>3：自己ループ</option></select></label>${arc}<label class="field"><span>条件・説明</span><textarea id="i-label" placeholder="○○だったら">${esc(x.label)}</textarea></label><label class="field"><span>線の色</span><select id="i-color">${COLORS.map(c=>`<option value="${c}" ${x.color===c?"selected":""}>${c}</option>`).join("")}</select></label><div class="inspector-actions"><button id="i-reverse" ${kind==="self"?"disabled":""}>向きを反転</button><button id="i-delete" class="danger">削除</button></div>`;bindInput("#i-label",v=>x.label=v);$("#i-edge-kind").onchange=e=>{history();x.kind=e.target.value;if(x.kind==="self")x.to=x.from;x.arcHeight=x.kind==="loopTop"?150:100;x.color=x.kind==="loopTop"?"#ff7da8":x.kind==="loopBottom"?"#ffd36b":x.kind==="self"?"#b196ff":COLORS[0];persist();render()};if($("#i-arc-height"))$("#i-arc-height").onchange=e=>{history();x.arcHeight=Math.max(75,grid25(Number(e.target.value)||100));persist();render()};$("#i-color").onchange=e=>{history();x.color=e.target.value;persist();render()};$("#i-reverse").onclick=()=>mutate(()=>[x.from,x.to]=[x.to,x.from]);$("#i-delete").onclick=()=>deleteEntity("edge",id)}
else{const g=group(id);if(!g)return clearSelection();const count=flow().cards.filter(c=>c.groupId===id).length;el.innerHTML=`<h2>グループ領域</h2><label class="field"><span>名前</span><input id="i-name" value="${attr(g.name)}"></label><label class="field"><span>色（子カードにも反映）</span><select id="i-color">${COLORS.map(c=>`<option value="${c}" ${g.color===c?"selected":""}>${c}</option>`).join("")}</select></label><p class="hint">子カード ${count}件。カードを領域内へ移動すると所属し、領域と一緒に移動します。</p><div class="inspector-actions"><button id="i-lock">${g.locked?"ロック解除":"領域をロック"}</button><button id="i-fit">子カードに合わせる</button><button id="i-delete" class="danger">削除</button></div>`;bindInput("#i-name",v=>g.name=v);$("#i-color").onchange=e=>{history();g.color=e.target.value;persist();render()};$("#i-lock").onclick=()=>mutate(()=>g.locked=!g.locked);$("#i-fit").onclick=()=>mutate(()=>fitGroup(g));$("#i-delete").onclick=()=>deleteEntity("group",id)}}
