function monthLabel(start,offset){const [y,m]=String(start).split("-").map(Number),d=new Date(y,m-1+offset,1);return`${d.getFullYear()}年 ${d.getMonth()+1}月`}
function shiftMonth(start,offset){const [y,m]=String(start).split("-").map(Number),d=new Date(y,m-1+offset,1);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`}
function snapCardToTimeline(c){c.x=grid25(c.x);c.y=grid25(c.y)}
