function moveTimeline(e){if(e.button!==0)return;e.preventDefault();e.stopPropagation();const t=flow().timeline,layer=$("#timeline-layer"),start={clientX:e.clientX,clientY:e.clientY,x:t.x,y:t.y,snap:snapshot(),moved:false,pointerId:e.pointerId},move=ev=>{if(ev.pointerId!==start.pointerId)return;if((ev.buttons&1)===0)return end(ev);const x=grid25(start.x+(ev.clientX-start.clientX)/app.view.zoom),y=grid25(start.y+(ev.clientY-start.clientY)/app.view.zoom);if(x!==t.x||y!==t.y)start.moved=true;t.x=x;t.y=y;layer.style.left=x+"px";layer.style.top=y+"px"},end=ev=>{if(ev?.pointerId!=null&&ev.pointerId!==start.pointerId)return;window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",end,true);window.removeEventListener("pointercancel",end,true);window.removeEventListener("blur",end);if(start.moved){app.history.undo.push(start.snap);app.history.redo=[];persist();updateHistory()}};window.addEventListener("pointermove",move);window.addEventListener("pointerup",end,true);window.addEventListener("pointercancel",end,true);window.addEventListener("blur",end)}
