function changeTimelineAxis(action,type,index){const t=flow().timeline;if(action==="insert"&&type==="row"){const m=timelineMetrics(),height=t.rowHeights[Math.max(0,index-1)]||150,boundary=t.y+m.rowY[index];mutate(()=>{t.rows.splice(index,0,"新しい項目");t.rowColors.splice(index,0,nextTimelineRowColor(t.rowColors,index));t.rowHeights.splice(index,0,height);flow().cards.forEach(c=>{if(c.y+cardHeight(c)/2>=boundary)c.y=grid25(c.y+height)});flow().groups.forEach(g=>{if(g.y>=boundary)g.y=grid25(g.y+height);else if(g.y+g.h>boundary)g.h=grid25(g.h+height)})});return}if(action==="add"){if(type==="col"){if(t.monthCount>=24)return toast("列は24件までです");mutate(()=>{t.monthCount++;t.colWidths.push(t.colWidths.at(-1)||300);t.colLabels.push("")})}else mutate(()=>{const rowIndex=t.rows.length;t.rows.push(`項目${rowIndex+1}`);t.rowColors.push(nextTimelineRowColor(t.rowColors,rowIndex));t.rowHeights.push(t.rowHeights.at(-1)||150)});return}if(type==="col"){if(t.monthCount<=1)return toast("最後の列は削除できません");mutate(()=>{t.colWidths.splice(index,1);t.colLabels.splice(index,1);t.monthCount--;if(index===0)t.startMonth=shiftMonth(t.startMonth,1)})}else{if(t.rows.length<=1)return toast("最後の項目は削除できません");mutate(()=>{t.rows.splice(index,1);t.rowColors.splice(index,1);t.rowHeights.splice(index,1)})}}
function toggleTimeline(){mutate(()=>flow().timeline.enabled=!flow().timeline.enabled);if(flow().timeline.enabled)fitView()}
function openTimelineSettings(){const t=flow().timeline;modal(`<h2>時系列の軸設定</h2><label class="field"><span>開始月</span><input id="tl-start" type="month" value="${attr(t.startMonth)}"></label><label class="field"><span>表示する月数（1〜24）</span><input id="tl-count" type="number" min="1" max="24" value="${t.monthCount}"></label><label class="field"><span>縦軸の項目（1行に1項目）</span><textarea id="tl-rows" placeholder="人名、部署、案件、役割など自由に設定">${esc(t.rows.join("\n"))}</textarea></label><p class="hint">見出しは表の上でダブルクリックして直接変更できます。各幅・高さもキャンバス上で変更できます。</p><div class="modal-actions"><button data-close>キャンセル</button><button id="save-timeline" class="primary">反映</button></div>`);$("#save-timeline").onclick=()=>{const rows=$("#tl-rows").value.split("\n").map(x=>x.trim()).filter(Boolean);history();t.startMonth=$("#tl-start").value||t.startMonth;const oldCols=t.colWidths,oldLabels=t.colLabels,oldRows=t.rowHeights,oldColors=t.rowColors;t.monthCount=Math.max(1,Math.min(24,Number($("#tl-count").value)||4));t.rows=rows.length?rows:["項目1"];t.colWidths=Array.from({length:t.monthCount},(_,i)=>oldCols[i]||300);t.colLabels=Array.from({length:t.monthCount},(_,i)=>oldLabels[i]||"");t.rowHeights=Array.from({length:t.rows.length},(_,i)=>oldRows[i]||150);t.rowColors=oldColors.slice(0,t.rows.length);while(t.rowColors.length<t.rows.length)t.rowColors.push(nextTimelineRowColor(t.rowColors,t.rowColors.length));persist();closeModal();render();fitView()}}
function addCard(text){const lines=text.trim().split(/\n/),title=lines.shift()||"新しいカード",body=lines.join("\n");const center=screenWorld((innerWidth+260-300)/2,innerHeight/2);mutate(()=>{const c={id:uid("card"),title,body,tags:[],collapsed:false,w:250,h:100,x:grid25(center.x-125),y:grid25(center.y-50)};flow().cards.push(c)})}
function addGroup(){const center=screenWorld((innerWidth+260-300)/2,innerHeight/2);mutate(()=>flow().groups.push({id:uid("group"),name:"新しい領域",color:COLORS[flow().groups.length%COLORS.length],x:grid25(center.x-200),y:grid25(center.y-120),w:400,h:250}))}
