function exportPng(){const bounds=exportBounds();if(bounds.w>32767||bounds.h>32767||bounds.w*bounds.h>120000000)return toast("PNG範囲が大きすぎます。図を小さく分けてください");const canvas=document.createElement("canvas");canvas.width=bounds.w;canvas.height=bounds.h;const ctx=canvas.getContext("2d");if(!ctx)return toast("PNG作成に失敗しました");ctx.fillStyle="#07090f";ctx.fillRect(0,0,bounds.w,bounds.h);ctx.save();ctx.translate(-bounds.x,-bounds.y);ctx.strokeStyle="rgba(125,166,220,.055)";ctx.lineWidth=1;for(let x=Math.floor(bounds.x/36)*36;x<bounds.x+bounds.w;x+=36){ctx.beginPath();ctx.moveTo(x,bounds.y);ctx.lineTo(x,bounds.y+bounds.h);ctx.stroke()}for(let y=Math.floor(bounds.y/36)*36;y<bounds.y+bounds.h;y+=36){ctx.beginPath();ctx.moveTo(bounds.x,y);ctx.lineTo(bounds.x+bounds.w,y);ctx.stroke()}pngTimeline(ctx);pngGroups(ctx);pngEdges(ctx);pngCards(ctx);ctx.restore();canvas.toBlob(blob=>{if(!blob)return toast("PNG作成に失敗しました");const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`${safeFileName(flow().name)}-全体.png`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`PNGを書き出しました（${bounds.w}×${bounds.h}px）`)},"image/png")}
function createFlowPngBlob(){const bounds=exportBounds();if(bounds.w>32767||bounds.h>32767||bounds.w*bounds.h>120000000)return Promise.reject(Error("PNG範囲が大きすぎます"));const canvas=document.createElement("canvas");canvas.width=bounds.w;canvas.height=bounds.h;const ctx=canvas.getContext("2d");if(!ctx)return Promise.reject(Error("PNG作成に失敗しました"));ctx.fillStyle="#07090f";ctx.fillRect(0,0,bounds.w,bounds.h);ctx.save();ctx.translate(-bounds.x,-bounds.y);ctx.strokeStyle="rgba(125,166,220,.055)";ctx.lineWidth=1;for(let x=Math.floor(bounds.x/36)*36;x<bounds.x+bounds.w;x+=36){ctx.beginPath();ctx.moveTo(x,bounds.y);ctx.lineTo(x,bounds.y+bounds.h);ctx.stroke()}for(let y=Math.floor(bounds.y/36)*36;y<bounds.y+bounds.h;y+=36){ctx.beginPath();ctx.moveTo(bounds.x,y);ctx.lineTo(bounds.x+bounds.w,y);ctx.stroke()}pngTimeline(ctx);pngGroups(ctx);pngEdges(ctx);pngCards(ctx);ctx.restore();return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error("PNG作成に失敗しました")),"image/png"))}
function aiCardPosition(c){const f=flow();if(!f.timeline.enabled){const ordered=[...f.cards].sort((a,b)=>a.x-b.x||a.y-b.y),index=ordered.findIndex(x=>x.id===c.id)+1;return`自由配置（左から${index}番目）`}const m=timelineMetrics(),right=c.x+cardWidth(c),bottom=c.y+cardHeight(c),periods=[],rows=[],tx=f.timeline.x,ty=f.timeline.y;for(let i=0;i<f.timeline.monthCount;i++)if(right>tx+m.colX[i]&&c.x<tx+m.colX[i+1])periods.push(timelineColumnLabel(i));for(let i=0;i<f.timeline.rows.length;i++)if(bottom>ty+m.rowY[i]&&c.y<ty+m.rowY[i+1])rows.push(f.timeline.rows[i]);return`${periods.length?periods.join("〜"):"時系列軸外"}／${rows.length?rows.join("・"):"項目軸外"}`}
function mdText(value){return String(value??"").replace(/\r?\n/g," ").replace(/\|/g,"／").trim()}
function mermaidText(value){return mdText(value).replace(/["[\]{}]/g,"").slice(0,80)}
function buildAiContext(){const f=flow(),cards=[...f.cards].sort((a,b)=>a.x-b.x||a.y-b.y),groups=[...f.groups].sort((a,b)=>a.x-b.x||a.y-b.y),cardIds=new Map(cards.map((c,i)=>[c.id,`C${String(i+1).padStart(2,"0")}`])),groupIds=new Map(groups.map((g,i)=>[g.id,`G${String(i+1).padStart(2,"0")}`])),incoming=new Map(cards.map(c=>[c.id,0])),outgoing=new Map(cards.map(c=>[c.id,0]));f.edges.forEach(e=>{if(incoming.has(e.to))incoming.set(e.to,incoming.get(e.to)+1);if(outgoing.has(e.from))outgoing.set(e.from,outgoing.get(e.from)+1)});const lines=[`# ${mdText(f.name)}`,"","> Flow FragmentsからAI相談用に書き出した文脈です。構造化された接続情報を主に読み、FLOW.pngで位置関係と領域の広がりを補完してください。","",`- 書き出し日時: ${new Date().toLocaleString("ja-JP")}`,`- カード: ${cards.length}件`,`- 接続: ${f.edges.length}件`,`- グループ: ${groups.length}件`,""];if(f.timeline.enabled){lines.push("## 軸の意味","",`- 横軸: ${Array.from({length:f.timeline.monthCount},(_,i)=>timelineColumnLabel(i)).map(mdText).join("／")}`,`- 縦軸: ${f.timeline.rows.map(mdText).join("／")}`,`- 行の色: ${f.timeline.rows.map((row,i)=>`${mdText(row)}=${f.timeline.rowColors[i]||COLORS[i%COLORS.length]}`).join("／")}`,"- カードが複数の期間・項目にまたがる場合は、該当範囲をすべて記載しています。","")}else lines.push("## 配置の意味","","- 自由配置キャンバスです。カードの左右関係を大まかな進行順として記載しています。","");lines.push("## グループ","");if(!groups.length)lines.push("- グループなし","");groups.forEach(g=>{const members=cards.filter(c=>c.groupId===g.id).map(c=>cardIds.get(c.id));lines.push(`### ${groupIds.get(g.id)}: ${mdText(g.name)}`,`- 子カード: ${members.length?members.join("、"):"なし"}`,`- 色: ${g.color||"未設定"}`,`- ロック: ${g.locked?"あり":"なし"}`,"")});lines.push("## カード","");cards.forEach(c=>{const parent=group(c.groupId);lines.push(`### ${cardIds.get(c.id)}: ${mdText(c.title)}`,`- 位置: ${aiCardPosition(c)}`,`- グループ: ${parent?`${groupIds.get(parent.id)} ${mdText(parent.name)}`:"なし"}`,`- 表示色: ${cardVisualColor(c)}`,`- タグ: ${c.tags.length?c.tags.map(t=>`#${mdText(t)}`).join("、"):"なし"}`,`- メモ: ${c.body?mdText(c.body):"なし"}`,`- 入ってくる接続: ${incoming.get(c.id)||0}本`,`- 出ていく接続: ${outgoing.get(c.id)||0}本`,"")});lines.push("## 接続関係","");if(!f.edges.length)lines.push("- 接続なし","");const kindNames={normal:"通常フロー",loopTop:"上側の戻りループ",loopBottom:"下側の差し戻し",self:"自己ループ"};f.edges.forEach((e,i)=>{const from=cardIds.get(e.from),to=cardIds.get(e.to);if(!from||!to)return;lines.push(`${i+1}. ${from}「${mdText(card(e.from)?.title)}」 → ${to}「${mdText(card(e.to)?.title)}」`,`   - 種類: ${kindNames[e.kind||"normal"]||e.kind}`,`   - 条件・説明: ${e.label?mdText(e.label):"記載なし"}`)});const starts=cards.filter(c=>!incoming.get(c.id)),ends=cards.filter(c=>!outgoing.get(c.id)),branches=cards.filter(c=>outgoing.get(c.id)>1),merges=cards.filter(c=>incoming.get(c.id)>1),isolated=cards.filter(c=>!incoming.get(c.id)&&!outgoing.get(c.id)),loops=f.edges.filter(e=>(e.kind||"normal")!=="normal");lines.push("","## 構造上の特徴","",`- 開始候補: ${starts.length?starts.map(c=>`${cardIds.get(c.id)}「${mdText(c.title)}」`).join("、"):"なし"}`,`- 終了候補: ${ends.length?ends.map(c=>`${cardIds.get(c.id)}「${mdText(c.title)}」`).join("、"):"なし"}`,`- 分岐元: ${branches.length?branches.map(c=>`${cardIds.get(c.id)}（${outgoing.get(c.id)}経路）`).join("、"):"なし"}`,`- 合流先: ${merges.length?merges.map(c=>`${cardIds.get(c.id)}（${incoming.get(c.id)}経路）`).join("、"):"なし"}`,`- ループ接続: ${loops.length}本`,`- 孤立カード: ${isolated.length?isolated.map(c=>cardIds.get(c.id)).join("、"):"なし"}`,"","## Mermaid形式の接続図","","> 以下は接続構造を機械的に確認するための図です。実際の空間配置はFLOW.pngを参照してください。","", "```mermaid","flowchart LR");cards.forEach(c=>lines.push(`  ${cardIds.get(c.id)}["${mermaidText(c.title)}"]`));f.edges.forEach(e=>{const from=cardIds.get(e.from),to=cardIds.get(e.to);if(!from||!to)return;const loop=(e.kind||"normal")!=="normal",label=mermaidText(e.label||(loop?kindNames[e.kind]:""));lines.push(`  ${from} ${loop?"-.->":"-->"}${label?`|"${label}"|`:""} ${to}`)});lines.push("```","","## 添付ファイル","","- `FLOW.png`: 位置関係、グループ範囲、時系列上の距離を視覚的に確認する画像","- `FLOW_DATA.json`: 座標やサイズを含む現在のフローの詳細データ","");return lines.join("\n")}
function buildAiJson(){const f=flow(),cards=[...f.cards].sort((a,b)=>a.x-b.x||a.y-b.y);return JSON.stringify({schema:"flow-fragments-ai-context-v1",generatedAt:new Date().toISOString(),flow:structuredClone(f),semanticCardIds:Object.fromEntries(cards.map((c,i)=>[c.id,`C${String(i+1).padStart(2,"0")}`]))},null,2)}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
let zipCrcTable=null;
function zipCrc(data){if(!zipCrcTable)zipCrcTable=Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0});let crc=0xffffffff;for(const byte of data)crc=zipCrcTable[(crc^byte)&255]^(crc>>>8);return(crc^0xffffffff)>>>0}
function zipHeader(size){return{bytes:new Uint8Array(size),view:null}}
function zipSet16(v,o,n){v.setUint16(o,n,true)}function zipSet32(v,o,n){v.setUint32(o,n>>>0,true)}
async function createZip(entries){const enc=new TextEncoder(),parts=[],central=[];let offset=0;const now=new Date(),dosTime=(now.getHours()<<11)|(now.getMinutes()<<5)|(now.getSeconds()>>1),dosDate=((now.getFullYear()-1980)<<9)|((now.getMonth()+1)<<5)|now.getDate();for(const entry of entries){const name=enc.encode(entry.name),data=entry.data instanceof Blob?new Uint8Array(await entry.data.arrayBuffer()):entry.data instanceof Uint8Array?entry.data:enc.encode(String(entry.data)),crc=zipCrc(data),local=zipHeader(30);local.view=new DataView(local.bytes.buffer);zipSet32(local.view,0,0x04034b50);zipSet16(local.view,4,20);zipSet16(local.view,6,0x0800);zipSet16(local.view,8,0);zipSet16(local.view,10,dosTime);zipSet16(local.view,12,dosDate);zipSet32(local.view,14,crc);zipSet32(local.view,18,data.length);zipSet32(local.view,22,data.length);zipSet16(local.view,26,name.length);parts.push(local.bytes,name,data);const center=zipHeader(46);center.view=new DataView(center.bytes.buffer);zipSet32(center.view,0,0x02014b50);zipSet16(center.view,4,20);zipSet16(center.view,6,20);zipSet16(center.view,8,0x0800);zipSet16(center.view,10,0);zipSet16(center.view,12,dosTime);zipSet16(center.view,14,dosDate);zipSet32(center.view,16,crc);zipSet32(center.view,20,data.length);zipSet32(center.view,24,data.length);zipSet16(center.view,28,name.length);zipSet32(center.view,42,offset);central.push(center.bytes,name);offset+=30+name.length+data.length}const centralSize=central.reduce((n,p)=>n+p.length,0),end=zipHeader(22);end.view=new DataView(end.bytes.buffer);zipSet32(end.view,0,0x06054b50);zipSet16(end.view,8,entries.length);zipSet16(end.view,10,entries.length);zipSet32(end.view,12,centralSize);zipSet32(end.view,16,offset);return new Blob([...parts,...central,end.bytes],{type:"application/zip"})}
async function exportAiPackage(){const button=$("#export-context"),old=button.textContent;button.disabled=true;button.textContent="作成中…";try{const markdown=buildAiContext(),png=await createFlowPngBlob(),json=buildAiJson(),zip=await createZip([{name:"AI_CONTEXT.md",data:markdown},{name:"FLOW.png",data:png},{name:"FLOW_DATA.json",data:json}]);downloadBlob(zip,`${safeFileName(flow().name)}-AI文脈.zip`);toast("AI用の文脈一式を書き出しました")}catch(e){toast(e.message||"文脈の書き出しに失敗しました")}finally{button.disabled=false;button.textContent=old;closeContextMenu()}}
async function copyAiContext(){const text=buildAiContext();try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement("textarea");area.value=text;area.style.position="fixed";area.style.opacity="0";document.body.appendChild(area);area.select();document.execCommand("copy");area.remove()}toast("AI用文脈をコピーしました");closeContextMenu()}
function exportAiMarkdown(){downloadBlob(new Blob([buildAiContext()],{type:"text/markdown;charset=utf-8"}),`${safeFileName(flow().name)}-AI_CONTEXT.md`);toast("Markdownを書き出しました");closeContextMenu()}
function closeContextMenu(){const control=$("#context-export-control"),menu=$("#context-export-menu"),toggle=$("#context-menu-toggle");control?.classList.remove("open");menu?.classList.add("hidden");toggle?.setAttribute("aria-expanded","false")}
function initContextExport(){const control=$("#context-export-control"),menu=$("#context-export-menu"),toggle=$("#context-menu-toggle");$("#export-context").onclick=exportAiPackage;toggle.onclick=e=>{e.stopPropagation();const open=menu.classList.toggle("hidden");control.classList.toggle("open",!open);toggle.setAttribute("aria-expanded",String(!open))};$$("[data-context-action]",menu).forEach(button=>button.onclick=()=>{const action=button.dataset.contextAction;if(action==="package")exportAiPackage();else if(action==="copy")copyAiContext();else if(action==="markdown")exportAiMarkdown();else if(action==="png"){exportPng();closeContextMenu()}});document.addEventListener("pointerdown",e=>{if(!e.target.closest("#context-export-control"))closeContextMenu()})}
function openFileDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(FILE_DB,1);req.onupgradeneeded=()=>req.result.createObjectStore(FILE_STORE,{keyPath:"id"});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function readRecentFiles(){try{const db=await openFileDb();return await new Promise((resolve,reject)=>{const req=db.transaction(FILE_STORE,"readonly").objectStore(FILE_STORE).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)})}catch{return[]}}
async function storeRecentFile(entry){try{const db=await openFileDb();await new Promise((resolve,reject)=>{const tx=db.transaction(FILE_STORE,"readwrite");tx.objectStore(FILE_STORE).put(entry);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch{}}
async function deleteRecentFile(id){try{const db=await openFileDb();await new Promise((resolve,reject)=>{const tx=db.transaction(FILE_STORE,"readwrite");tx.objectStore(FILE_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch{}}
function renderRecentFiles(){const select=$("#recent-file-select");select.innerHTML='<option value="">最近のファイル</option>'+app.recentFiles.map(x=>`<option value="${attr(x.id)}">${esc(x.name)}</option>`).join("");select.value=app.recentFiles.some(x=>x.id===app.currentFileId)?app.currentFileId:"";$("#forget-file").disabled=!select.value}
async function rememberFile(handle){let entry=null;for(const item of app.recentFiles){try{if(item.handle&&await handle.isSameEntry(item.handle)){entry=item;break}}catch{}}if(!entry)entry={id:uid("file"),name:handle.name,handle,updatedAt:Date.now()};entry.name=handle.name;entry.handle=handle;entry.updatedAt=Date.now();app.currentFileId=entry.id;app.currentFileHandle=handle;app.recentFiles=[entry,...app.recentFiles.filter(x=>x.id!==entry.id)].slice(0,12);await storeRecentFile(entry);renderRecentFiles()}
async function loadExternalState(file,handle=null){try{const data=JSON.parse(await file.text());if(data.app!=="Flow Fragments"||!Array.isArray(data.flows))throw Error();history();app.state=data;app.activeFlowId=data.activeFlowId||data.flows[0].id;app.selected=null;app.filterTag="";normalize();persist();render();fitView();if(handle)await rememberFile(handle);$("#save-status").textContent=handle?`${handle.name} を開いています`:"JSONを読み込みました";toast(`${file.name}を開きました`)}catch{toast("対応していないJSONです")}}
async function requestHandlePermission(handle,mode="read"){if(!handle)return false;const opts={mode};if((await handle.queryPermission?.(opts))==="granted")return true;return(await handle.requestPermission?.(opts))==="granted"}
async function openExternalFile(){if(window.showOpenFilePicker){try{const[handle]=await showOpenFilePicker({types:[{description:"Flow Fragments JSON",accept:{"application/json":[".json"]}}],multiple:false});await loadExternalState(await handle.getFile(),handle)}catch(e){if(e.name!=="AbortError")toast("ファイルを開けませんでした")}return}$("#file-input").click()}
async function openRecentFile(id){const entry=app.recentFiles.find(x=>x.id===id);if(!entry?.handle)return;if(!await requestHandlePermission(entry.handle,"read"))return toast("ファイルを開く権限がありません");await loadExternalState(await entry.handle.getFile(),entry.handle)}
async function writeCurrentHandle(handle){if(!await requestHandlePermission(handle,"readwrite"))throw Error("permission");const writable=await handle.createWritable();await writable.write(JSON.stringify(app.state,null,2));await writable.close();await rememberFile(handle);$("#save-status").textContent=`${handle.name} に保存済み`;toast(`${handle.name}に上書き保存しました`)}
async function saveAsExternalFile(){if(window.showSaveFilePicker){try{const handle=await showSaveFilePicker({suggestedName:`${safeFileName(flow().name)}.json`,types:[{description:"Flow Fragments JSON",accept:{"application/json":[".json"]}}]});await writeCurrentHandle(handle)}catch(e){if(e.name!=="AbortError")toast("保存できませんでした")}return}exportJson()}
async function saveExternalFile(){if(app.currentFileHandle){try{return await writeCurrentHandle(app.currentFileHandle)}catch{toast("上書きできません。別名保存を試してください")}}else await saveAsExternalFile()}
async function forgetCurrentFile(){const id=$("#recent-file-select").value;if(!id)return;await deleteRecentFile(id);app.recentFiles=app.recentFiles.filter(x=>x.id!==id);if(app.currentFileId===id){app.currentFileId="";app.currentFileHandle=null}renderRecentFiles();toast("プルダウンから削除しました")}
async function initFileControls(){app.recentFiles=(await readRecentFiles()).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,12);renderRecentFiles();$("#import-json").onclick=openExternalFile;$("#export-json").onclick=saveExternalFile;$("#save-as-json").onclick=saveAsExternalFile;$("#recent-file-select").onchange=e=>e.target.value&&openRecentFile(e.target.value);$("#forget-file").onclick=forgetCurrentFile;$("#file-input").onchange=e=>{if(e.target.files[0])loadExternalState(e.target.files[0]);e.target.value=""}}
function exportJson(){const blob=new Blob([JSON.stringify(app.state,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${safeFileName(flow().name)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast("JSONを書き出しました")}
async function importJson(file){try{const data=JSON.parse(await file.text());if(data.app!=="Flow Fragments"||!Array.isArray(data.flows))throw Error();history();app.state=data;app.activeFlowId=data.activeFlowId||data.flows[0].id;normalize();persist();render();fitView();toast("JSONを読み込みました")}catch{toast("対応していないJSONです")}}
function newFlow(){modal(`<h2>新しいフローチャート</h2><label class="field"><span>名前</span><input id="new-flow-name" value="新しいフロー" autofocus></label><div class="modal-actions"><button data-close>キャンセル</button><button id="create-flow" class="primary">作成</button></div>`);$("#create-flow").onclick=()=>{const f=emptyFlow($("#new-flow-name").value.trim()||"新しいフロー");history();app.state.flows.push(f);app.activeFlowId=f.id;app.state.activeFlowId=f.id;app.selected=null;persist();closeModal();render()}}
function deleteFlow(){if(app.state.flows.length===1)return toast("最後のフローは削除できません");if(!confirm(`「${flow().name}」を削除しますか？`))return;mutate(()=>{app.state.flows=app.state.flows.filter(f=>f.id!==app.activeFlowId);app.activeFlowId=app.state.flows[0].id;app.state.activeFlowId=app.activeFlowId;app.selected=null;app.multiSelected.clear()})}
function duplicateFlow(){app.panCleanup?.();history();const source=flow(),copy=structuredClone(source),groupMap=new Map(),cardMap=new Map();copy.id=uid("flow");copy.name=`${source.name} のコピー`;copy.createdAt=new Date().toISOString();copy.groups.forEach(g=>{const old=g.id;g.id=uid("group");groupMap.set(old,g.id)});copy.cards.forEach(c=>{const old=c.id;c.id=uid("card");c.groupId=groupMap.get(c.groupId)||"";cardMap.set(old,c.id)});copy.edges=copy.edges.map(e=>({...e,id:uid("edge"),from:cardMap.get(e.from),to:cardMap.get(e.to)})).filter(e=>e.from&&e.to);app.state.flows.push(copy);app.activeFlowId=copy.id;app.state.activeFlowId=copy.id;app.selected=null;app.multiSelected.clear();app.view={x:90,y:110,zoom:1};persist();render();fitView();toast("フローを複製しました")}
function bind(){const vp=$("#viewport");vp.onpointerdown=e=>{if(e.button!==0||e.target!==vp&&e.target!==$("#world")&&e.target.id!=="edge-layer"&&!e.target.closest(".timeline-grid"))return;if(app.selected){app.selected=null;renderInspector();renderWorld()}const st={x:e.clientX,y:e.clientY,vx:app.view.x,vy:app.view.y,pointerId:e.pointerId};vp.classList.add("panning");try{vp.setPointerCapture(e.pointerId)}catch{}const endPan=()=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",endPan,true);window.removeEventListener("pointercancel",endPan,true);window.removeEventListener("blur",endPan);vp.classList.remove("panning");try{if(vp.hasPointerCapture(st.pointerId))vp.releasePointerCapture(st.pointerId)}catch{}};const move=ev=>{if(ev.pointerId!==st.pointerId)return;if((ev.buttons&1)===0)return endPan();app.view.x=st.vx+ev.clientX-st.x;app.view.y=st.vy+ev.clientY-st.y;updateTransform()};window.addEventListener("pointermove",move);window.addEventListener("pointerup",endPan,true);window.addEventListener("pointercancel",endPan,true);window.addEventListener("blur",endPan)};vp.onwheel=e=>{e.preventDefault();const before=screenWorld(e.clientX,e.clientY),rect=vp.getBoundingClientRect(),z=Math.max(.3,Math.min(2.2,app.view.zoom*(e.deltaY>0?.9:1.1)));app.view.zoom=z;app.view.x=e.clientX-rect.left-before.x*z;app.view.y=e.clientY-rect.top-before.y*z;updateTransform()};$("#quick-add").onsubmit=e=>{e.preventDefault();const t=$("#quick-text").value;if(!t.trim())return;addCard(t);$("#quick-text").value=""};$("#quick-text").onkeydown=e=>{if(e.ctrlKey&&e.key==="Enter")$("#quick-add").requestSubmit()};$("#new-flow").onclick=newFlow;$("#add-group").onclick=addGroup;$("#auto-layout").onclick=autoLayout;$("#fit-view").onclick=fitView;$("#timeline-toggle").onclick=toggleTimeline;$("#timeline-settings").onclick=openTimelineSettings;$("#undo").onclick=undo;$("#redo").onclick=redo;$("#export-json").onclick=exportJson;$("#import-json").onclick=()=>$("#file-input").click();$("#file-input").onchange=e=>{if(e.target.files[0])importJson(e.target.files[0]);e.target.value=""};$("#clear-tag").onclick=()=>{app.filterTag="";render()};$("#flow-title").onchange=e=>mutate(()=>flow().name=e.target.value.trim()||"名称未設定");$("#flow-title").oncontextmenu=e=>{e.preventDefault();deleteFlow()};window.onkeydown=e=>{const editing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName),mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(mod&&key==="z"){e.preventDefault();e.shiftKey?redo():undo()}else if(mod&&key==="y"){e.preventDefault();redo()}else if(mod&&key==="c"&&!editing){e.preventDefault();copySelected()}else if(mod&&key==="v"&&!editing){e.preventDefault();pasteSelected()}else if(e.key==="Delete"&&app.selected&&!editing)deleteEntity(app.selected.type,app.selected.id)};$("#modal-root").onclick=e=>{if(e.target.matches(".modal-backdrop,[data-close]"))closeModal()}}
function panViewport(e){if(e.button!==0)return;const vp=$("#viewport"),st={x:e.clientX,y:e.clientY,vx:app.view.x,vy:app.view.y,pointerId:e.pointerId};vp.classList.add("panning");const end=()=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",end,true);window.removeEventListener("pointercancel",end,true);window.removeEventListener("blur",end);vp.classList.remove("panning")};const move=ev=>{if(ev.pointerId!==st.pointerId)return;if((ev.buttons&1)===0)return end();app.view.x=st.vx+ev.clientX-st.x;app.view.y=st.vy+ev.clientY-st.y;updateTransform()};window.addEventListener("pointermove",move);window.addEventListener("pointerup",end,true);window.addEventListener("pointercancel",end,true);window.addEventListener("blur",end)}
function selectLockedGroupAndPan(e,id){if(e.button!==0)return;if(e.shiftKey){app.multiGroups.has(id)?app.multiGroups.delete(id):app.multiGroups.add(id);app.selected=app.multiSelected.size||app.multiGroups.size?{type:"group",id}:null;render();return}if(!app.multiGroups.has(id)){app.multiSelected.clear();app.multiGroups.clear();app.multiGroups.add(id)}app.selected={type:"group",id};renderInspector();renderWorld();panViewport(e)}
function startStablePan(e,clearSelection=false){if(e.button!==0)return;app.panCleanup?.();const vp=$("#viewport"),st={x:e.clientX,y:e.clientY,vx:app.view.x,vy:app.view.y,pointerId:e.pointerId};if(clearSelection&&(app.selected||app.multiSelected.size)){app.selected=null;app.multiSelected.clear();renderInspector();renderWorld()}vp.classList.add("panning");document.body.classList.add("is-interacting");const paint=()=>{app.panFrame=0;updateTransform()},move=ev=>{if(ev.pointerId!==st.pointerId)return;if((ev.buttons&1)===0)return end();app.view.x=st.vx+ev.clientX-st.x;app.view.y=st.vy+ev.clientY-st.y;if(!app.panFrame)app.panFrame=requestAnimationFrame(paint)},visibility=()=>{if(document.hidden)end()},end=ev=>{if(ev?.pointerId!=null&&ev.pointerId!==st.pointerId)return;app.panCleanup=null;window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",end,true);window.removeEventListener("pointercancel",end,true);window.removeEventListener("blur",end);document.removeEventListener("visibilitychange",visibility);vp.removeEventListener("lostpointercapture",end);if(app.panFrame){cancelAnimationFrame(app.panFrame);app.panFrame=0}updateTransform();vp.classList.remove("panning");document.body.classList.remove("is-interacting");try{if(vp.hasPointerCapture(st.pointerId))vp.releasePointerCapture(st.pointerId)}catch{}};app.panCleanup=end;window.addEventListener("pointermove",move);window.addEventListener("pointerup",end,true);window.addEventListener("pointercancel",end,true);window.addEventListener("blur",end);document.addEventListener("visibilitychange",visibility);vp.addEventListener("lostpointercapture",end);try{vp.setPointerCapture(st.pointerId)}catch{}}
function updateTimelineProximity(e){const layer=$("#timeline-layer");if(!layer.classList.contains("timeline-grid"))return;const r=layer.getBoundingClientRect(),near=58,scaleY=r.height/(parseFloat(layer.style.height)||r.height);layer.classList.toggle("near-right",Math.abs(e.clientX-r.right)<=near&&e.clientY>=r.top-near&&e.clientY<=r.bottom+near);layer.classList.toggle("near-bottom",Math.abs(e.clientY-r.bottom)<=near&&e.clientX>=r.left-near&&e.clientX<=r.right+near);$$("[data-insert-row]",layer).forEach(button=>{const boundary=r.top+Number(button.dataset.boundaryY)*scaleY;button.classList.toggle("near",Math.abs(e.clientY-boundary)<=34&&e.clientX>=r.left-near&&e.clientX<=r.right+near)})}
function installStablePan(){const vp=$("#viewport");vp.onpointerdown=e=>{if(e.button!==0||e.target.closest(".flow-card,.group-box,[data-edge],button,input,textarea,select,.timeline-month,.timeline-row-label,.timeline-corner,.axis-resize"))return;if(e.target===vp||e.target===$("#world")||e.target.closest("#world"))startStablePan(e,true)};vp.addEventListener("pointermove",updateTimelineProximity);vp.addEventListener("pointerleave",()=>{$("#timeline-layer").classList.remove("near-right","near-bottom")});panViewport=e=>startStablePan(e,false)}
function bindMultiSelectionClear(){document.addEventListener("pointerdown",e=>{if(e.target.closest("[data-edge]")){app.multiSelected.clear();app.multiGroups.clear()}if(e.button===0&&!e.shiftKey&&(e.target===$("#viewport")||e.target===$("#world")||e.target.id==="edge-layer"||e.target.closest(".timeline-grid"))){app.multiSelected.clear();app.multiGroups.clear()}},true)}
function updateTransform(){$("#world").style.transform=`translate(${app.view.x}px,${app.view.y}px) scale(${app.view.zoom})`}
function screenWorld(x,y){const r=$("#viewport").getBoundingClientRect();return{x:(x-r.left-app.view.x)/app.view.zoom,y:(y-r.top-app.view.y)/app.view.zoom}}
function filtered(c){return!app.filterTag||c.tags.includes(app.filterTag)}function sel(t,id){return(t==="card"?app.multiSelected:app.multiGroups).has(id)?"selected":app.selected?.type===t&&app.selected.id===id?"selected":""}function esc(v=""){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}function attr(v=""){return esc(v)}
